class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        ListNode prev = dummy;
        ListNode curr = head;

        while (curr != null) {
            boolean duplicate = false;
            while (curr.next != null && curr.val == curr.next.val) {
                duplicate = true;
                curr = curr.next;
            }
            if (duplicate) {
                prev.next = curr.next;
            } else {
                prev = prev.next;
            }
            curr = curr.next;
        }

        return dummy.next;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        ListNode sentinel = new ListNode(0);
        ListNode tail = sentinel;
        ListNode read = head;

        while (read != null) {
            ListNode first = read;
            int value = read.val;
            int count = 0;
            while (read != null && read.val == value) {
                count++;
                read = read.next;
            }
            if (count == 1) {
                tail.next = first;
                tail = first;
            }
        }

        tail.next = null;
        return sentinel.next;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        if (head.val == head.next.val) {
            int value = head.val;
            while (head != null && head.val == value) {
                head = head.next;
            }
            return deleteDuplicates(head);
        }

        head.next = deleteDuplicates(head.next);
        return head;
    }
}

import java.util.*;

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (ListNode node = head; node != null; node = node.next) {
            counts.merge(node.val, 1, Integer::sum);
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (ListNode node = head; node != null; node = node.next) {
            if (counts.get(node.val) == 1) {
                tail.next = new ListNode(node.val);
                tail = tail.next;
            }
        }
        return dummy.next;
    }
}

class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        if (head == null) {
            return null;
        }

        ListNode write = head;
        boolean wrote = false;
        ListNode read = head;

        while (read != null) {
            int value = read.val;
            int count = 0;
            while (read != null && read.val == value) {
                count++;
                read = read.next;
            }
            if (count == 1) {
                if (!wrote) {
                    write = head;
                    wrote = true;
                } else {
                    write = write.next;
                }
                write.val = value;
            }
        }

        if (!wrote) {
            return null;
        }
        write.next = null;
        return head;
    }
}
